import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

gelu_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

#define CEIL_DIV(a, b) ((a + b - 1) / b)

__forceinline__ __device__ float gelu_function(float x) {
    const float sqrt_2_over_pi = 0.7978845608028654f;
    const float coef = 0.044715f;
    return 0.5f * x * (1.0f + tanhf(sqrt_2_over_pi * x * (1.0f + coef * x * x)));
}

__global__ void gelu_forward_kernel(const float* input, float* output, int num_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        output[idx] = gelu_function(input[idx]);
    }
}

torch::Tensor gelu_cuda_forward(torch::Tensor x) {
    auto output = torch::empty_like(x);
    int num_elements = x.numel();

    const int threads_per_block = 256;
    int num_blocks = CEIL_DIV(num_elements, threads_per_block);

    gelu_forward_kernel<<<num_blocks, threads_per_block>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        num_elements
    );

    return output;
}
"""

gelu_cpp_source = "torch::Tensor gelu_cuda_forward(torch::Tensor x);"

gelu_extension = load_inline(
    name="gelu_extension",
    cpp_sources=gelu_cpp_source,
    cuda_sources=gelu_source,
    functions=["gelu_cuda_forward"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return gelu_extension.gelu_cuda_forward(x.cuda())
